property_tests.invariant_check:
result = validate(spec)
if len(result.errors) == 0:
    assert result.valid == True

result = validate(spec)
for group in spec.groups:
    total_refs = sum(len(s.test_spec_refs or []) for s in group.subtasks if not s.id.endswith('.V'))
    if total_refs > 15:
        assert any(group_id_in_warning(w, group.id) for w in result.warnings), f"No warning for group {group.id} with {total_refs} refs"

result = validate(spec)
for group in spec.groups:
    non_v_count = len([s for s in group.subtasks if not s.id.endswith('.V')])
    if non_v_count > 6:
        assert any(group_id_in_warning(w, group.id) for w in result.warnings), f"No warning for group {group.id} with {non_v_count} subtasks"

result = validate(spec)
for group in spec.groups:
    for subtask in group.subtasks:
        if subtask.id.endswith('.V'):
            continue
        if len(subtask.test_spec_refs or []) > 8:
            assert any(subtask.id in str(w) for w in result.warnings), f"No warning for subtask {subtask.id}"
